class GameEventV1(
    RootModel[
        GameSnapshotEventV1
        | GameMoveCommittedEventV1
        | GameClockSyncEventV1
        | GameTakebackAppliedEventV1
        | AnalysisReadyEventV1
        | CoachReadyEventV1
        | ResyncRequiredEventV1
        | GameStatusChangedEventV1
    ]
):
    root: (
        GameSnapshotEventV1
        | GameMoveCommittedEventV1
        | GameClockSyncEventV1
        | GameTakebackAppliedEventV1
        | AnalysisReadyEventV1
        | CoachReadyEventV1
        | ResyncRequiredEventV1
        | GameStatusChangedEventV1
    ) = Field(
        ...,
        description="Read-only server-to-client stream. Discriminate by type before consuming payload; unknown event types fail validation. Snapshot/resync control frames carry a cursor but are handled separately from durable event dedup. Matchmaking has REST polling, not a game stream event.",
    )
